import{_ as s,o as t,a as e,b as n}from"./app.C56HXsMI.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"调试接口","link":"/api/SIMD-API/basic_api/debug_interface/debug_interface"},{"text":"异常检测","link":"/api/SIMD-API/basic_api/debug_interface/exception_detection/exception_detection"},{"text":"ascendc_assert","link":"/api/SIMD-API/basic_api/debug_interface/exception_detection/ascendc_assert"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/debug_interface/exception_detection/ascendc_assert.md","filePath":"api/SIMD-API/basic_api/debug_interface/exception_detection/ascendc_assert.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787050286000}'),i={name:"api/SIMD-API/basic_api/debug_interface/exception_detection/ascendc_assert.md"};function l(c,a,p,d,r,h){return t(),e("div",null,[...a[0]||(a[0]=[n(`<div><article class="markdown-body"><h1>ascendc_assert<span id="ZH-CN_TOPIC_0000002506195843"></span></h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section259105813316"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;utils/debug/asc_assert.h&quot;</code>。</p><p>ascendc_assert提供了一种在CPU/NPU域实现断言功能的接口。当断言条件不满足时，系统会输出断言信息并格式化打印在屏幕上。</p><p>在算子核函数（Kernel）侧实现代码中需要增加断言的地方使用ascendc_assert检查代码，并格式化输出一些调测信息。</p><div class="callout callout-caution"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M4.47.22A.749.749 0 0 1 5 0h6c.199 0 .389.079.53.22l4.25 4.25c.141.14.22.331.22.53v6a.749.749 0 0 1-.22.53l-4.25 4.25A.749.749 0 0 1 11 16H5a.749.749 0 0 1-.53-.22L.22 11.53A.749.749 0 0 1 0 11V5c0-.199.079-.389.22-.53Zm.84 1.28L1.5 5.31v5.38l3.81 3.81h5.38l3.81-3.81V5.31L10.69 1.5ZM8 4a.75.75 0 0 1 .75.75v3.5a.75.75 0 0 1-1.5 0v-3.5A.75.75 0 0 1 8 4Zm0 8a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>注意</p><p>该接口主要用于调试分析，开启后会对算子性能产生一定影响，通常在调试阶段使用，生产环境建议关闭。<br> 默认情况下，调用该接口就会打印相关内容，开发者可以参考<a href="../disable_ascendc_dump.html">关闭ASCENDC_DUMP说明</a>，按需关闭该接口功能。</p></div><h2 id="函数原型">函数原型<span id="section2067518173415"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#define ascendc_assert(expr)</span>
<span class="cp">#define ascendc_assert(expr, __gm__ const char *fmt, Args&amp;&amp;... args)</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="section158061867342"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>expr</td><td>输入</td><td>assert断言是否终止程序的条件。为true则程序继续执行，为false则终止程序。</td></tr><tr><td>fmt</td><td>输入</td><td>格式控制字符串，包含两种类型的对象：普通字符和转换说明。<br>•普通字符将原样不动地打印输出。<br>•转换说明并不直接输出而是用于控制printf中参数的转换和打印。每个转换说明都由一个百分号字符（%）开始，以转换说明结束，从而说明输出数据的类型。<br>•支持的转换类型包括：<br>  ▪%d / %i：输出十进制数，支持打印的数据类型：bool、int8_t、int16_t、int32_t、int64_t。<br>  ▪%f：输出实数，支持打印的数据类型：float、half。<br>  ▪%x：输出十六进制整数，支持打印的数据类型：int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、int64_t、uint64_t。<br>  ▪%s：输出字符串。<br>  ▪%u：输出unsigned类型数据，支持打印的数据类型：bool、uint8_t、uint16_t、uint32_t、uint64_t。<br>  ▪%p：输出指针地址。<br><strong>注意</strong>：<br>•上文列出的数据类型是NPU域调试支持的数据类型，CPU域调试时，支持的数据类型和C/C++规范保持一致。<br>•在转换类型为%x，即输出十六进制整数时，NPU域上的输出为64位，CPU域上的输出为32位。</td></tr><tr><td>args</td><td>输入</td><td>附加参数，个数和类型可变的参数列表：根据不同的fmt字符串，函数可能需要一系列的附加参数，每个参数包含了一个要被插入的值，替换了fmt参数中指定的每个%标签。参数的个数应与%标签的个数相同。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p>无</p><h2 id="返回值说明">返回值说明<span id="section640mcpsimp"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section43265506459"></span><a class="header-anchor" href="#约束说明">​</a></h2><p>单次调用本接口打印的数据总量不可超过30KB。使用时应注意，如果超出这个限制，则数据不会被打印。</p><h2 id="调用示例">调用示例<span id="section82241477610"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>接口调用示例</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">int</span><span class="w"> </span><span class="n">assertFlag</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">10</span><span class="p">;</span>

<span class="c1">// 格式化打印</span>
<span class="n">ascendc_assert</span><span class="p">(</span><span class="n">assertFlag</span><span class="w"> </span><span class="o">!=</span><span class="w"> </span><span class="mi">10</span><span class="p">,</span><span class="w"> </span><span class="s">&quot;The assertFlag value is %d.</span><span class="se">\\n</span><span class="s">&quot;</span><span class="p">,</span><span class="w"> </span><span class="n">assertFlag</span><span class="p">);</span>
</code></pre></div><p>程序运行时会触发assert，打印效果如下：</p><div class="code-block"><pre class="highlight"><code>[ASSERT] /home/.../add_custom.cpp:44: Assertion \`assertFlag != 10&#39; The assertFlag value is 10.
</code></pre></div></article></div>`,1)])])}const u=s(i,[["render",l]]);export{_ as __pageData,u as default};
